import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"

/**
 * The AI's plan as numbered steps on one rail. Only the current step can be applied.
 * `draft` (confidence 50–79) asks for a review before Apply.
 */
export type StepState = "upcoming" | "current" | "draft" | "applying" | "done" | "failed"

export interface PlanStep {
  when: string
  title: React.ReactNode
  state: StepState
  /** Required when failed. */
  reason?: string
}

export interface PlanRailProps {
  steps: PlanStep[]
  onApply?: (index: number) => void
  onReview?: (index: number) => void
  className?: string
}

export function PlanRail({ steps, onApply, onReview, className }: PlanRailProps) {
  return (
    <ol data-slot="plan-rail" className={cn("m-0 grid list-none p-0", className)}>
      {steps.map((s, i) => {
        const live = s.state === "current" || s.state === "draft" || s.state === "applying"
        return (
          <li key={i} data-state={s.state} className="relative grid grid-cols-[22px_1fr] gap-3 pb-5 last:pb-0">
            {i < steps.length - 1 && <span className="absolute top-[26px] bottom-1 left-[10.5px] w-px bg-border" />}
            <span
              className={cn(
                "grid size-[22px] place-items-center font-mono text-[11px] shadow-[inset_0_0_0_1px_var(--border)]",
                live && "bg-signal text-on-signal shadow-none",
                s.state === "done" && "bg-foreground text-background shadow-none",
                s.state === "failed" && "text-signal shadow-[inset_0_0_0_1.5px_var(--gc-accent)]"
              )}
            >
              {s.state === "done" ? "✓" : i + 1}
            </span>
            <div className="grid gap-1">
              <span className={cn("text-[13px]", live ? "text-signal" : "text-muted-foreground")}>{s.state === "draft" ? `${s.when} · Draft` : s.when}</span>
              <span className={cn(s.state === "done" && "text-muted-foreground")}>{s.title}</span>
              {s.state === "failed" && s.reason && <span className="text-[13px] text-signal">{s.reason}</span>}
              {live && (
                <div className="mt-1.5 flex items-center gap-3">
                  {s.state === "draft" ? (
                    <Button variant="secondary" size="sm" onClick={() => onReview?.(i)}>Review first</Button>
                  ) : (
                    <Button size="sm" loading={s.state === "applying"} onClick={() => onApply?.(i)}>{s.state === "applying" ? "Applying…" : "Apply"}</Button>
                  )}
                  {s.state === "applying" ? <Spinner className="hidden" /> : <span className="text-[13px] text-muted-foreground">You can undo anytime</span>}
                </div>
              )}
            </div>
          </li>
        )
      })}
    </ol>
  )
}
